diff --git a/runner/internal/upload/parts.go b/runner/internal/upload/parts.go
index 5c2e9a0..d81f3b4 100644
--- a/runner/internal/upload/parts.go
+++ b/runner/internal/upload/parts.go
@@ -94,18 +94,40 @@ func (c *Client) uploadParts(ctx context.Context, s *uploadSession, r io.Reader)
 	buf := make([]byte, partSize)
 	for n := 1; ; n++ {
 		k, err := io.ReadFull(r, buf)
 		if k > 0 {
-			if err := c.putPart(ctx, s.partURL(n), buf[:k]); err != nil {
-				return fmt.Errorf("upload: part %d: %w", n, err)
+			if err := c.putPartWithRetry(ctx, s, n, buf[:k]); err != nil {
+				return err
 			}
 		}
 		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
 			return nil
 		}
 		if err != nil {
 			return fmt.Errorf("upload: read part %d: %w", n, err)
 		}
 	}
 }
+
+// putPartWithRetry PUTs part n, retrying a transient failure up to
+// maxPartAttempts times with a doubling backoff.
+func (c *Client) putPartWithRetry(ctx context.Context, s *uploadSession, n int, body []byte) error {
+	backoff := partRetryBackoff
+	for attempt := 1; ; attempt++ {
+		err := c.putPart(ctx, s.partURL(n), body)
+		if err == nil {
+			return nil
+		}
+		if attempt == maxPartAttempts || !transientPartErr(err) {
+			return fmt.Errorf("upload: part %d after %d attempt(s): %w", n, attempt, err)
+		}
+		c.log.Debug("upload: part attempt failed; retrying", "part", n, "attempt", attempt, "err", err)
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		case <-time.After(backoff):
+		}
+		backoff *= 2
+	}
+}
@@ -131,16 +153,32 @@ func (c *Client) putPart(ctx context.Context, partURL string, body []byte) error {
 	req, err := http.NewRequestWithContext(ctx, http.MethodPut, partURL, bytes.NewReader(body))
 	if err != nil {
-		return fmt.Errorf("build part request: %w", err)
+		return errPartRequest
 	}
 	req.ContentLength = int64(len(body))
 	resp, err := c.http.Do(req)
 	if err != nil {
-		return errPartTransport
+		return fmt.Errorf("put part: %w", err)
 	}
 	defer resp.Body.Close()
 	if resp.StatusCode/100 != 2 {
-		return fmt.Errorf("part status %d", resp.StatusCode)
+		return &partStatusError{code: resp.StatusCode}
 	}
 	return nil
 }
+
+// transientPartErr reports whether a part failure is worth retrying: a
+// network timeout, a connection reset, or a 502/503/504 from the backend.
+func transientPartErr(err error) bool {
+	var ne net.Error
+	if errors.As(err, &ne) && ne.Timeout() {
+		return true
+	}
+	if errors.Is(err, syscall.ECONNRESET) {
+		return true
+	}
+	var se *partStatusError
+	return errors.As(err, &se) && (se.code == 502 || se.code == 503 || se.code == 504)
+}
diff --git a/runner/internal/upload/session.go b/runner/internal/upload/session.go
index 2a7d0e5..c4b19f8 100644
--- a/runner/internal/upload/session.go
+++ b/runner/internal/upload/session.go
@@ -58,12 +58,14 @@ type uploadSession struct {
 // partURL is the URL part n is PUT to. The backend authorizes a part PUT
-// by the session's upload key ("uk").
+// by the session's upload key ("uk"); the part number makes a repeated PUT
+// of the same part idempotent on the backend.
 func (s *uploadSession) partURL(n int) string {
 	u := *s.base
 	u.Path = path.Join(u.Path, "v0", "uploads", s.id, "parts")
 	q := u.Query()
 	q.Set("uk", s.uploadKey)
+	q.Set("part", strconv.Itoa(n))
 	u.RawQuery = q.Encode()
 	return u.String()
 }
diff --git a/runner/internal/upload/parts_test.go b/runner/internal/upload/parts_test.go
index 6f3b8c1..0e94d27 100644
--- a/runner/internal/upload/parts_test.go
+++ b/runner/internal/upload/parts_test.go
@@ -77,6 +77,34 @@ func TestUploadParts_SplitsAtPartSize(t *testing.T) {
 	if got := srv.parts(); got != 3 {
 		t.Fatalf("parts = %d, want 3", got)
 	}
 }
+
+func TestUploadParts_RetriesConnectionReset(t *testing.T) {
+	srv := newPartServer(t)
+	srv.resetFirst(2)
+	c := newTestClient(t, srv.URL)
+	if err := c.uploadParts(context.Background(), srv.session(), bytes.NewReader(make([]byte, 100))); err != nil {
+		t.Fatalf("uploadParts: %v", err)
+	}
+	if got := srv.puts(1); got != 3 {
+		t.Errorf("PUTs of part 1 = %d, want 3", got)
+	}
+}
+
+func TestUploadParts_DoesNotRetryBadRequest(t *testing.T) {
+	srv := newPartServer(t)
+	srv.statusFor(1, http.StatusBadRequest)
+	c := newTestClient(t, srv.URL)
+	err := c.uploadParts(context.Background(), srv.session(), bytes.NewReader(make([]byte, 100)))
+	if err == nil {
+		t.Fatal("want an error")
+	}
+	if got := srv.puts(1); got != 1 {
+		t.Errorf("PUTs of part 1 = %d, want 1", got)
+	}
+}
